# Generated by build.py from recipe.yml for recipe https-require-a-client-certificate. Do not edit.
set -e
cd "$(dirname "$0")"
mkdir -p site open
printf '%s\n' 'hello from surl' > site/hello.txt
printf '%s\n' 'hello from surl' > open/hello.txt
printf '%s\n' 'not a certificate' > notes.txt
openssl req -x509 -newkey rsa:2048 -nodes -keyout ca.key -out ca.pem -days 30 -subj "/CN=Test Device CA" -addext "basicConstraints=critical,CA:TRUE" -addext "keyUsage=critical,keyCertSign"
openssl req -x509 -newkey rsa:2048 -nodes -keyout other-ca.key -out other-ca.pem -days 30 -subj "/CN=Other Device CA" -addext "basicConstraints=critical,CA:TRUE" -addext "keyUsage=critical,keyCertSign"
openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1"
openssl req -newkey rsa:2048 -nodes -keyout client.key -out client.csr -subj "/CN=device-1"
openssl x509 -req -in client.csr -CA ca.pem -CAkey ca.key -CAcreateserial -out client.pem -days 30
openssl req -newkey rsa:2048 -nodes -keyout stranger.key -out stranger.csr -subj "/CN=device-1"
openssl x509 -req -in stranger.csr -CA other-ca.pem -CAkey other-ca.key -CAcreateserial -out stranger.pem -days 30
openssl pkcs12 -export -in client.pem -inkey client.key -out client.p12 -passout pass:s3cret
openssl pkcs12 -export -in stranger.pem -inkey stranger.key -out stranger.p12 -passout pass:s3cret
surl --directory site --log-file tls.log --cert server.pem --key server.key --cacert ca.pem https://127.0.0.1:8080/ &
sleep 1
curl -sS --cacert server.pem --cert client.p12:s3cret --cert-type P12 https://127.0.0.1:8080/hello.txt
kill $(jobs -p)
